quiz.answer:
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
)

type User struct {
	Name string `json:"name"`
	Age  int    `json:"age"`
}

// createUserHandler を書く。
// - POST 以外: http.Error で "Method not allowed"(405)
// - ボディの JSON を User に Decode できなければ: http.Error で "Bad request"(400)
// - 成功したら: fmt.Printf で "Received: 名前, 年齢" と改行を出し、
//   Content-Type を application/json にして 201 で user を JSON で返す
func createUserHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var user User
	err := json.NewDecoder(r.Body).Decode(&user)
	if err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	fmt.Printf("Received: %s, %d\n", user.Name, user.Age)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(user)
}

// ---- ここから下は動作確認用(書き換え不要) ----
var _ = json.Marshal // 雛形のままでもビルドできるようにするための行

// 標準入力の1行 = 1リクエスト。「メソッド」または「メソッド ボディ」の形。
// 各リクエストについて「ステータスコード Content-Type ボディ」を1行で表示する。
func main() {
	sc := bufio.NewScanner(os.Stdin)
	for sc.Scan() {
		method, body, _ := strings.Cut(sc.Text(), " ")
		req := httptest.NewRequest(method, "/users", strings.NewReader(body))
		rec := httptest.NewRecorder()
		createUserHandler(rec, req)
		res := rec.Result()
		fmt.Printf("%d %q %q\n", res.StatusCode, res.Header.Get("Content-Type"), rec.Body.String())
	}
}

