quiz.answer:
package main

import (
	"encoding/json"
	"fmt"
	"os"
)

type Item struct {
	Name  string `json:"name"`
	Price int    `json:"price"`
}

func main() {
	var item Item
	err := json.NewDecoder(os.Stdin).Decode(&item)
	if err != nil {
		fmt.Println("error")
		return
	}
	fmt.Printf("name=%s price=%d\n", item.Name, item.Price)
}
